"use client";

import React, { useState, useMemo } from "react";
import { 
  CalendarDays, MapPin, Sparkles, Globe, 
  ChevronDown, ArrowRight, PartyPopper 
} from "lucide-react";

/* --- 1. INTELLIGENT DATA STORE --- */
const HOLIDAYS_DB = [
  // 2025
  { id: 1, name: "New Year's Day", date: "Jan 01", day: "Wednesday", year: "2025", type: "Public", region: "Global" },
  { id: 2, name: "Republic Day", date: "Jan 26", day: "Sunday", year: "2025", type: "National", region: "India" },
  { id: 3, name: "Holi", date: "Mar 14", day: "Friday", year: "2025", type: "Optional", region: "North India" },
  { id: 4, name: "Good Friday", date: "Apr 18", day: "Friday", year: "2025", type: "Public", region: "Global" },
  { id: 5, name: "Independence Day", date: "Aug 15", day: "Friday", year: "2025", type: "National", region: "India" },
  { id: 6, name: "Diwali", date: "Oct 20", day: "Monday", year: "2025", type: "Public", region: "India" },
  
  // 2026
  { id: 7, name: "New Year's Day", date: "Jan 01", day: "Thursday", year: "2026", type: "Public", region: "Global" },
  { id: 8, name: "Republic Day", date: "Jan 26", day: "Monday", year: "2026", type: "National", region: "India" },
  { id: 9, name: "Ugadi / Gudi Padwa", date: "Mar 19", day: "Thursday", year: "2026", type: "Optional", region: "Telangana" },
  { id: 10, name: "Good Friday", date: "Apr 03", day: "Friday", year: "2026", type: "Public", region: "Global" },
  { id: 11, name: "Labor Day", date: "May 01", day: "Friday", year: "2026", type: "Public", region: "Global" },
  { id: 12, name: "Christmas", date: "Dec 25", day: "Friday", year: "2026", type: "Public", region: "Global" },
];

export default function PremiumHolidayUI() {
  const [year, setYear] = useState("2026");
  const [region, setRegion] = useState("All");
  const [type, setType] = useState("All");

  // --- SMART FILTERING ---
  const filtered = useMemo(() => {
    return HOLIDAYS_DB.filter(h => {
      const yearMatch = h.year === year;
      const typeMatch = type === "All" || h.type === type;
      const regionMatch = region === "All" || h.region === "Global" || h.region === region || (h.region === "India" && region !== "Global");
      return yearMatch && typeMatch && regionMatch;
    });
  }, [year, region, type]);

  return (
    <div className="min-h-screen bg-[#F4F5F7] dark:bg-[#09090b] text-slate-900 dark:text-slate-100 font-sans pb-20">
      
      {/* --- 1. THE HERO SECTION --- */}
      <div className="bg-white dark:bg-[#09090b] px-6 lg:px-12 pt-12 pb-24 border-b border-slate-200 dark:border-slate-800 relative overflow-hidden">
        {/* Abstract Background Decoration */}
        <div className="absolute top-0 right-0 w-[400px] h-[400px] bg-brand-500/5 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2 pointer-events-none" />

        <div className="max-w-4xl mx-auto relative z-10">
           <div className="flex items-center gap-3 mb-4">
              <span className="px-3 py-1 rounded-full bg-slate-100 dark:bg-white/10 text-[10px] font-black uppercase tracking-widest text-slate-500 dark:text-slate-300 backdrop-blur-md">
                Time Governance
              </span>
              <div className="w-1 h-1 rounded-full bg-slate-300 dark:bg-slate-700" />
              <span className="text-[10px] font-bold text-brand-600 uppercase tracking-widest">
                FY {year}-{parseInt(year) + 1}
              </span>
           </div>
           
           <h1 className="text-5xl lg:text-7xl font-black tracking-tighter text-slate-900 dark:text-white mb-6">
             Holiday <span className="text-slate-300 dark:text-slate-700">Cal.</span>
           </h1>
           
           {/* THE FLOATING FILTER BAR */}
           <div className="flex flex-col md:flex-row gap-4 bg-white/80 dark:bg-white/5 backdrop-blur-xl p-2 rounded-2xl border border-slate-200 dark:border-white/10 shadow-2xl shadow-slate-200/50 dark:shadow-none w-full md:w-auto md:inline-flex">
              
              {/* Year Dropdown */}
              <div className="relative group">
                 <CalendarDays className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 group-hover:text-brand-500 transition-colors" />
                 <select 
                    value={year} 
                    onChange={(e) => setYear(e.target.value)}
                    className="w-full md:w-40 bg-transparent pl-10 pr-8 py-3 text-xs font-black uppercase tracking-widest text-slate-700 dark:text-slate-200 outline-none cursor-pointer appearance-none hover:bg-slate-50 dark:hover:bg-white/5 rounded-xl transition-colors"
                 >
                    <option value="2025" className="dark:bg-slate-900">2025 Series</option>
                    <option value="2026" className="dark:bg-slate-900">2026 Series</option>
                 </select>
                 <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 w-3 h-3 text-slate-300" />
              </div>

              <div className="hidden md:block w-[1px] bg-slate-200 dark:bg-white/10 my-2" />

              {/* Region Dropdown */}
              <div className="relative group">
                 <MapPin className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 group-hover:text-brand-500 transition-colors" />
                 <select 
                    value={region} 
                    onChange={(e) => setRegion(e.target.value)}
                    className="w-full md:w-48 bg-transparent pl-10 pr-8 py-3 text-xs font-black uppercase tracking-widest text-slate-700 dark:text-slate-200 outline-none cursor-pointer appearance-none hover:bg-slate-50 dark:hover:bg-white/5 rounded-xl transition-colors"
                 >
                    <option value="All" className="dark:bg-slate-900">All Locations</option>
                    <option value="Telangana" className="dark:bg-slate-900">Hyderabad (TS)</option>
                    <option value="North India" className="dark:bg-slate-900">Delhi (NCR)</option>
                    <option value="Global" className="dark:bg-slate-900">Remote / Global</option>
                 </select>
                 <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 w-3 h-3 text-slate-300" />
              </div>

              {/* Type Toggles */}
              <div className="flex bg-slate-100 dark:bg-white/5 rounded-xl p-1">
                 {['All', 'Public', 'Optional'].map(t => (
                    <button
                       key={t}
                       onClick={() => setType(t)}
                       className={`px-4 py-2 rounded-lg text-[9px] font-black uppercase tracking-widest transition-all ${
                          type === t 
                          ? 'bg-white dark:bg-brand-600 text-slate-900 dark:text-white shadow-sm' 
                          : 'text-slate-400 hover:text-slate-600 dark:hover:text-slate-300'
                       }`}
                    >
                       {t}
                    </button>
                 ))}
              </div>
           </div>
        </div>
      </div>

      {/* --- 2. THE TIMELINE FEED --- */}
      <div className="max-w-4xl mx-auto -mt-12 px-6 lg:px-0 relative z-20 space-y-4">
         {filtered.length > 0 ? filtered.map((h, i) => (
            <div 
              key={h.id}
              className="group flex flex-col md:flex-row items-stretch md:items-center bg-white dark:bg-[#121214] p-1 rounded-3xl border border-slate-200 dark:border-white/5 hover:border-brand-500/30 dark:hover:border-brand-500/30 transition-all hover:shadow-2xl hover:shadow-brand-500/5 overflow-hidden"
            >
               {/* Date Visual */}
               <div className="flex flex-row md:flex-col items-center justify-between md:justify-center gap-1 bg-slate-50 dark:bg-white/5 p-6 md:w-32 rounded-[1.25rem] group-hover:bg-brand-50 dark:group-hover:bg-brand-500/10 transition-colors">
                  <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">{h.date.split(' ')[0]}</span>
                  <span className="text-3xl font-black text-slate-900 dark:text-white leading-none">{h.date.split(' ')[1]}</span>
                  <span className="md:hidden text-xs font-bold text-slate-500 uppercase">{h.day}</span>
               </div>

               {/* Content */}
               <div className="flex-1 p-6 flex flex-col justify-center">
                  <div className="flex items-center gap-3 mb-2">
                     <span className={`px-2 py-0.5 rounded-md text-[9px] font-black uppercase tracking-widest flex items-center gap-1.5 ${
                        h.type === 'Optional' 
                        ? 'bg-amber-100 text-amber-700 dark:bg-amber-500/10 dark:text-amber-500' 
                        : 'bg-emerald-100 text-emerald-700 dark:bg-emerald-500/10 dark:text-emerald-500'
                     }`}>
                        {h.type === 'Optional' ? <Sparkles size={8} /> : <Globe size={8} />}
                        {h.type}
                     </span>
                     <div className="w-1 h-1 rounded-full bg-slate-200 dark:bg-slate-700" />
                     <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                        {h.region}
                     </span>
                  </div>
                  
                  <div className="flex justify-between items-end">
                     <div>
                        <h3 className="text-xl font-black tracking-tight text-slate-900 dark:text-white group-hover:text-brand-600 transition-colors">
                           {h.name}
                        </h3>
                        <p className="hidden md:block text-xs font-bold text-slate-400 mt-1 uppercase tracking-widest">
                           {h.day}
                        </p>
                     </div>
                     <ArrowRight className="text-slate-200 dark:text-slate-800 group-hover:text-brand-500 transition-all -translate-x-4 group-hover:translate-x-0 opacity-0 group-hover:opacity-100" />
                  </div>
               </div>
            </div>
         )) : (
            <div className="bg-white dark:bg-[#121214] rounded-3xl p-12 text-center border border-dashed border-slate-200 dark:border-white/10">
               <PartyPopper className="w-12 h-12 text-slate-300 mx-auto mb-4" />
               <p className="text-sm font-black text-slate-400 uppercase tracking-widest">No holidays found for this selection.</p>
            </div>
         )}
      </div>

    </div>
  );
}